for i in range(int(input())):
	n = int(input())
	b = []
	for i in range(n):
		a = list(input().split())
		b.append(a)
	for i in range(n - 1):
		if b[i + 1][0] == 'Right':
			b[i][0] = 'Left'
		else:
			b[i][0] = 'Right'
	b[n - 1][0] = 'Begin'
	final = b[::-1]
	for i in final:
		print(*i)
